css:
  #plv3{
    --bg:#0F0E13; --surface:#17151E; --soft:#1B1925;
    --ink:#E9E7EF; --ink-2:#C3BDD1; --ink-muted:#8B849C;
    --border:rgba(255,255,255,.08); --border-strong:rgba(255,255,255,.15);
    --brand:#34D399; --brand-hover:#10B981; --neon:#6EE7B7;
    --radius:18px;
    --spring:cubic-bezier(.34,1.56,.64,1);
  }
  #plv3 *{box-sizing:border-box;margin:0;padding:0}
  #plv3{scroll-behavior:smooth}
  #plv3{background:var(--bg);color:var(--ink);font-family:'Heebo',system-ui,sans-serif;
    line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
  #plv3 h1,#plv3 h2,#plv3 h3,#plv3 .display{font-family:'Rubik','Heebo',sans-serif;font-weight:800;line-height:1.14;letter-spacing:-.01em}
  #plv3 a{color:inherit;text-decoration:none}
  #plv3 .wrap{max-width:1180px;margin-inline:auto;padding-inline:24px}
  #plv3 .brand-text{color:var(--brand)} #plv3 .neon-text{color:var(--neon)}
  #plv3 section{padding-block:104px}

  /* glow */
  #plv3 .glow-bg{position:absolute;inset:0;overflow:hidden;z-index:0;pointer-events:none}
  #plv3 .glow-bg::before{content:"";position:absolute;top:-25%;inset-inline-start:50%;transform:translateX(-50%);
    width:760px;height:760px;border-radius:50%;background:radial-gradient(circle,rgba(52,211,153,.20),transparent 62%);filter:blur(34px)}

  /* nav */
  #plv3 header{position:sticky;top:0;z-index:100;backdrop-filter:blur(14px);background:rgba(18,20,19,.72);border-bottom:1px solid var(--border)}
  #plv3 nav{display:flex;align-items:center;justify-content:space-between;height:68px}
  #plv3 .logo{display:flex;align-items:center;gap:9px;font-family:'Rubik';font-weight:800;font-size:21px}
  #plv3 .logo .dot{width:11px;height:11px;border-radius:50%;background:var(--brand);box-shadow:0 0 14px var(--brand);transition:transform .6s var(--spring)}
  #plv3 .logo:hover .dot{transform:rotate(180deg) scale(1.4)}
  #plv3 .nav-links{display:flex;gap:30px;align-items:center}
  #plv3 .nav-links a{color:var(--ink-2);font-size:15px;font-weight:500;transition:color .2s;position:relative}
  #plv3 .nav-links a::after{content:"";position:absolute;inset-inline:0;bottom:-4px;height:2px;background:var(--brand);transform:scaleX(0);transform-origin:center;transition:transform .25s var(--spring)}
  #plv3 .nav-links a:hover{color:var(--ink)} #plv3 .nav-links a:hover::after{transform:scaleX(1)}
  #plv3 .nav-cta{display:flex;gap:12px;align-items:center}
  #plv3 .btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;
    padding:0 22px;border-radius:12px;font-weight:700;font-size:15px;cursor:pointer;border:1px solid transparent;
    transition:transform .2s var(--spring),box-shadow .2s,background-color .2s;font-family:inherit}
  #plv3 .btn-primary{background:var(--brand);color:#06130D}
  #plv3 .btn-primary:hover{background:var(--brand-hover);transform:translateY(-2px);box-shadow:0 8px 24px rgba(52,211,153,.30)}
  #plv3 .btn-ghost{background:transparent;color:var(--ink);border-color:var(--border-strong)}
  #plv3 .btn-ghost:hover{border-color:var(--brand);color:var(--brand)}
  #plv3 .lang{color:var(--ink-muted);font-size:14px;font-weight:600}
  #plv3 .burger{display:none;background:none;border:0;color:var(--ink);font-size:26px;cursor:pointer}

  /* ===== HERO ===== */
  #plv3 .hero{position:relative;padding:80px 0 64px;text-align:center}
  #plv3 .hero .wrap{position:relative;z-index:1}
  #plv3 .pill{display:inline-flex;align-items:center;gap:8px;padding:7px 16px;border:1px solid var(--border-strong);
    border-radius:999px;font-size:13.5px;color:var(--ink-2);background:var(--surface);margin-bottom:28px;
    opacity:0;transform:translateY(10px);animation:fadeUp .6s var(--spring) .1s forwards}
  #plv3 .pill .live{width:8px;height:8px;border-radius:50%;background:var(--neon);box-shadow:0 0 10px var(--neon);animation:pulse 1.8s infinite}
  @keyframes pulse{50%{opacity:.35}}
  @keyframes fadeUp{to{opacity:1;transform:none}}
  #plv3 .hero h1{font-size:clamp(34px,6vw,64px);margin-bottom:22px}
  /* hero unfold: each line masked, inner slides up with spring stagger */
  #plv3 .unfold{display:block;overflow:hidden}
  #plv3 .unfold>span{display:block;transform:translateY(112%);animation:unfold .9s var(--spring) forwards}
  #plv3 .unfold:nth-child(1)>span{animation-delay:.15s}
  #plv3 .unfold:nth-child(2)>span{animation-delay:.30s}
  @keyframes unfold{to{transform:none}}
  #plv3 .from{color:var(--ink-muted);font-weight:700}
  #plv3 .hl{position:relative;white-space:nowrap;color:var(--brand)}
  #plv3 .hl::after{content:"";position:absolute;inset-inline:0;bottom:4px;height:12px;background:rgba(52,211,153,.26);z-index:-1;border-radius:4px;
    transform:scaleX(0);transform-origin:right;animation:swipe .5s ease 1s forwards}
  @keyframes swipe{to{transform:scaleX(1)}}
  #plv3 .hero p.sub{font-size:clamp(17px,2.4vw,21px);color:var(--ink-2);max-width:660px;margin:0 auto 34px;opacity:0;animation:fadeUp .7s var(--spring) .55s forwards}
  #plv3 .hero-cta{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-bottom:18px;opacity:0;animation:fadeUp .7s var(--spring) .7s forwards}
  #plv3 .hero-cta .btn{min-height:52px;padding:0 30px;font-size:16.5px}
  #plv3 .micro{font-size:13.5px;color:var(--ink-muted);opacity:0;animation:fadeUp .7s var(--spring) .85s forwards}

  /* trust */
  #plv3 .trust{margin-top:44px;opacity:0;animation:fadeUp .8s var(--spring) 1s forwards}
  #plv3 .trust p{font-size:12.5px;letter-spacing:.14em;color:var(--ink-muted);text-transform:uppercase;margin-bottom:16px}
  #plv3 .trust-logos{display:flex;gap:34px;justify-content:center;align-items:center;flex-wrap:wrap}
  #plv3 .trust-logos span{font-family:'Rubik';font-weight:700;font-size:18px;color:var(--ink-2);filter:grayscale(1) opacity(.7);transition:filter .25s}
  #plv3 .trust-logos span:hover{filter:grayscale(0) opacity(1)}

  /* dashboard mock */
  #plv3 .mock{margin:54px auto 0;max-width:960px;border:1px solid var(--border-strong);border-radius:22px;
    background:linear-gradient(180deg,var(--surface),var(--bg));overflow:hidden;box-shadow:0 55px 100px rgba(0,0,0,.6);
    transform-style:preserve-3d;transform-origin:center;will-change:transform;transform:rotateX(60deg) scale(.9)}
  #plv3 .mock-bar{display:flex;align-items:center;gap:8px;padding:13px 18px;border-bottom:1px solid var(--border);background:rgba(0,0,0,.2)}
  #plv3 .mock-bar i{width:11px;height:11px;border-radius:50%;background:#3a3d3c;display:inline-block}
  #plv3 .mock-bar i:first-child{background:#ff5f57}#plv3 .mock-bar i:nth-child(2){background:#febc2e}#plv3 .mock-bar i:nth-child(3){background:#28c840}
  #plv3 .mock-bar .url{margin-inline-start:14px;font-size:12.5px;color:var(--ink-muted)}
  #plv3 .mock-body{display:grid;grid-template-columns:200px 1fr;min-height:340px}
  #plv3 .mock-side{border-inline-end:1px solid var(--border);padding:18px 14px;background:rgba(0,0,0,.12)}
  #plv3 .mock-side .m-logo{font-family:'Rubik';font-weight:800;margin-bottom:20px;font-size:15px}
  #plv3 .mock-side a{display:flex;align-items:center;gap:9px;padding:9px 11px;border-radius:9px;font-size:13.5px;color:var(--ink-muted);margin-bottom:3px}
  #plv3 .mock-side a.on{background:rgba(52,211,153,.14);color:var(--brand)}
  #plv3 .mock-side a .ic{width:15px;height:15px;border-radius:4px;background:currentColor;opacity:.7}
  #plv3 .mock-main{padding:22px}
  #plv3 .mock-main h4{font-size:15px;margin-bottom:16px;color:var(--ink)}
  #plv3 .m-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}
  #plv3 .m-card{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:14px}
  #plv3 .m-card .lbl{font-size:11.5px;color:var(--ink-muted);margin-bottom:6px}
  #plv3 .m-card .val{font-family:'Rubik';font-weight:800;font-size:22px}
  #plv3 .m-card .val.up{color:var(--neon)}
  #plv3 .m-bars{display:flex;align-items:flex-end;gap:9px;height:120px;padding:14px;background:var(--surface);border:1px solid var(--border);border-radius:12px}
  #plv3 .m-bars .b{flex:1;background:linear-gradient(180deg,var(--brand),rgba(52,211,153,.25));border-radius:6px 6px 3px 3px;height:0;transition:height .9s var(--spring)}
  #plv3 .mock-shot{display:block;width:100%;height:auto}
  #plv3 .tilt{transition:transform .35s var(--spring);will-change:transform}
  /* numbers always LTR so the minus sits on the left (correct in Hebrew) */
  #plv3 .stat,#plv3 .band .n,#plv3 .price .amt,#plv3 .m-card .val,#plv3 .rev .stat{direction:ltr;unicode-bidi:isolate}
  /* reclined "laid-down screen" rig (ported from ProductScreens) */
  #plv3 .mock-stage{perspective:1400px;perspective-origin:50% 40%}

  /* ===== how-it-works: timeline + steps lottie ===== */
  #plv3 .how-layout{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
  #plv3 .how-lottie{max-width:400px;margin-inline:auto;width:100%;filter:hue-rotate(0deg) saturate(1.25) brightness(1.02)}
  #plv3 .how-lottie>div{width:100%;aspect-ratio:4/3}
  #plv3 .how-lottie svg{display:block;width:100%!important;height:100%!important}
  #plv3 .timeline2{position:relative;padding-inline-start:30px}
  #plv3 .timeline2::before{content:"";position:absolute;inset-inline-start:6px;top:6px;bottom:6px;width:2px;background:var(--border-strong)}
  #plv3 .tl-fill{position:absolute;inset-inline-start:6px;top:6px;height:calc(100% - 12px);width:2px;background:var(--brand);
    transform-origin:top;transform:scaleY(0);transition:transform .12s linear}
  #plv3 .tl-step{position:relative;padding-bottom:32px;opacity:.4;transition:opacity .45s var(--spring)}
  #plv3 .tl-step.active{opacity:1}
  #plv3 .tl-step:last-child{padding-bottom:0}
  #plv3 .tl-dot{position:absolute;inset-inline-start:-30px;top:2px;width:14px;height:14px;border-radius:50%;background:var(--bg);
    border:2px solid var(--brand);box-shadow:0 0 0 4px rgba(52,211,153,.1);transition:background .3s,box-shadow .3s}
  #plv3 .tl-step.active .tl-dot{background:var(--brand);box-shadow:0 0 0 5px rgba(52,211,153,.25)}
  #plv3 .tl-num{font-family:'Rubik';font-weight:800;color:var(--brand);font-size:13px;letter-spacing:.05em;margin-bottom:4px}
  #plv3 .tl-step h3{font-size:18px;margin-bottom:6px}
  #plv3 .tl-step p{color:var(--ink-2);font-size:14.5px}

  /* bundle discount badge */
  #plv3 .price .save{position:absolute;top:16px;inset-inline-end:16px;font-size:11px;font-weight:700;color:var(--neon);
    background:rgba(110,231,183,.12);border:1px solid rgba(110,231,183,.3);padding:3px 9px;border-radius:999px}
  #plv3 .price .seats{font-size:13px;color:var(--brand);font-weight:700;margin-bottom:16px;display:flex;align-items:center;gap:6px}
  #plv3 .price .old{font-size:15px;color:var(--ink-muted);text-decoration:line-through;margin-inline-start:8px;font-weight:600}

  /* ===== offer bar (above the fold) ===== */
  #plv3 .offerbar{border-block:1px solid var(--border);background:linear-gradient(90deg,rgba(52,211,153,.12),transparent)}
  #plv3 .offerbar .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-block:16px;flex-wrap:wrap}
  #plv3 .ob-left{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
  #plv3 .ob-result{font-family:'Rubik';font-weight:800;font-size:17px;color:var(--ink)}
  #plv3 .ob-result b{color:var(--brand)}
  #plv3 .ob-badge{font-size:12.5px;color:var(--brand);border:1px solid rgba(52,211,153,.35);background:rgba(52,211,153,.1);padding:4px 11px;border-radius:999px}
  #plv3 .ob-cta{display:inline-flex;align-items:center;gap:8px;min-height:46px;padding:0 22px;border-radius:12px;background:var(--brand);color:#0c0a13;font-weight:700;transition:background .2s,transform .2s}
  #plv3 .ob-cta:hover{background:var(--brand-hover);transform:translateY(-1px)}

  /* ===== lead-capture form ===== */
  #plv3 .lead{padding-block:88px}
  #plv3 .lead .wrap{max-width:940px}
  #plv3 .lead-card{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:40px}
  #plv3 .lead-card.soft{background:var(--soft)}
  #plv3 .lead-eyebrow{color:var(--brand);font-weight:700;font-size:14px;margin-bottom:10px}
  #plv3 .lead-card h2{font-size:clamp(24px,3.5vw,32px);margin-bottom:8px}
  #plv3 .lead-sub{color:var(--ink-2);font-size:16px;margin-bottom:24px}
  #plv3 .ff{position:relative;margin-bottom:14px}
  #plv3 .ff input{width:100%;background:var(--bg);border:1px solid var(--border-strong);border-radius:12px;padding:22px 14px 8px;color:var(--ink);font-family:inherit;font-size:15px;min-height:56px}
  #plv3 .ff input:focus{outline:none;border-color:var(--brand)}
  #plv3 .ff label{position:absolute;inset-inline-start:15px;top:17px;color:var(--ink-muted);font-size:15px;pointer-events:none;transition:.18s var(--spring)}
  #plv3 .ff input:focus+label,#plv3 .ff input:not(:placeholder-shown)+label{top:8px;font-size:11px;color:var(--brand)}
  #plv3 .lead-check{display:flex;gap:9px;align-items:flex-start;margin:4px 0 18px;font-size:13.5px;color:var(--ink-2);cursor:pointer}
  #plv3 .lead-check input{margin-top:3px;accent-color:var(--brand);width:16px;height:16px;flex:none}
  #plv3 .lead-actions{display:flex;gap:12px;flex-wrap:wrap}
  #plv3 .lead-submit{flex:1;min-width:150px;min-height:50px;border:0;border-radius:12px;background:var(--brand);color:#0c0a13;font-weight:700;font-size:15.5px;cursor:pointer;font-family:inherit;transition:background .2s,transform .2s}
  #plv3 .lead-submit:hover{background:var(--brand-hover);transform:translateY(-1px)}
  #plv3 .lead-wa{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:50px;padding:0 20px;border-radius:12px;background:#25D366;color:#062e15;font-weight:700;font-size:15px;text-decoration:none;transition:filter .2s,transform .2s}
  #plv3 .lead-wa:hover{filter:brightness(1.08);transform:translateY(-1px)}
  #plv3 .lead-visual{border-radius:16px;min-height:250px;background:radial-gradient(circle at 30% 25%,rgba(52,211,153,.28),transparent 62%),var(--bg);border:1px solid var(--border);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:24px;text-align:center}
  #plv3 .lead-visual .big{font-size:56px}
  #plv3 .lead-visual .chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
  #plv3 .lead-visual .chips span{font-size:12.5px;color:var(--ink-2);background:var(--surface);border:1px solid var(--border);padding:5px 11px;border-radius:999px}
  #plv3 .lead-success{text-align:center;padding:34px 10px}
  #plv3 .lead-success .ic{font-size:44px;margin-bottom:10px}
  #plv3 .lead-success h3{font-size:22px;margin-bottom:6px}
  #plv3 .lead-success p{color:var(--ink-2)}
  /* prominent lead card under the hero screen */
  #plv3 .lead-hero .lead-card{border-color:rgba(52,211,153,.5);box-shadow:0 0 0 1px rgba(52,211,153,.35),0 30px 70px rgba(52,211,153,.12)}
  #plv3 .cta-wrap{position:relative;flex:1;min-width:150px;display:flex}
  #plv3 .cta-wrap .lead-submit{width:100%}
  #plv3 .lead-hero .lead-submit{animation:btnPulse 3.6s ease-in-out infinite}
  @keyframes btnPulse{0%,42%,68%,100%{box-shadow:0 0 0 0 rgba(52,211,153,0)}52%{box-shadow:0 0 0 8px rgba(52,211,153,.25)}}
  #plv3 .demo-cursor{position:absolute;z-index:6;inset-inline-start:50%;top:50%;width:24px;height:24px;pointer-events:none;
    filter:drop-shadow(0 2px 4px rgba(0,0,0,.5));animation:cursorDemo 3.6s cubic-bezier(.5,0,.2,1) infinite}
  @keyframes cursorDemo{
    0%{transform:translate(-10px,46px) scale(1);opacity:0}
    12%{opacity:1}
    40%{transform:translate(-12px,-4px) scale(1)}
    50%{transform:translate(-12px,-4px) scale(.72)}
    60%{transform:translate(-12px,-4px) scale(1)}
    88%{transform:translate(-12px,-4px) scale(1);opacity:1}
    100%{transform:translate(-10px,46px) scale(1);opacity:0}}
  @media(prefers-reduced-motion:reduce){#plv3 .demo-cursor,#plv3 .lead-hero .lead-submit{animation:none}#plv3 .demo-cursor{display:none}}

  /* ===== fixed side buttons ===== */
  #plv3 .fab{position:fixed;bottom:22px;z-index:120;display:inline-flex;align-items:center;gap:9px;min-height:52px;padding:0 20px;
    border-radius:999px;font-weight:700;font-size:15px;box-shadow:0 12px 32px rgba(0,0,0,.45);cursor:pointer;border:0;font-family:inherit;
    text-decoration:none;transition:transform .2s var(--spring),box-shadow .2s}
  #plv3 .fab:hover{transform:translateY(-2px)}
  #plv3 .fab-wa{inset-inline-start:22px;background:#25D366;color:#062e15}
  #plv3 .fab-pkg{inset-inline-end:22px;background:var(--brand);color:#0c0a13;transform:translateY(90px);opacity:0;transition:transform .4s var(--spring),opacity .4s}
  #plv3 .fab-pkg.show{transform:translateY(0);opacity:1}
  @media(max-width:560px){#plv3 .fab .lbl{display:none}#plv3 .fab{padding:0 15px;min-height:50px}}

  /* ===== referral pill (appears occasionally) ===== */
  #plv3 .refpill{position:fixed;bottom:88px;inset-inline-start:22px;z-index:119;max-width:250px;background:var(--surface);
    border:1px solid rgba(52,211,153,.4);border-radius:16px;padding:16px 18px 16px;box-shadow:0 16px 44px rgba(0,0,0,.55);
    transform:translateY(20px) scale(.96);opacity:0;pointer-events:none;transition:all .45s var(--spring)}
  #plv3 .refpill.show{transform:none;opacity:1;pointer-events:auto}
  #plv3 .refpill h4{font-size:15px;margin-bottom:6px;color:var(--ink)}
  #plv3 .refpill p{font-size:13px;color:var(--ink-2);margin-bottom:12px;line-height:1.5}
  #plv3 .refpill a{display:block;text-align:center;background:var(--brand);color:#0c0a13;font-weight:700;font-size:13.5px;padding:10px;border-radius:10px;text-decoration:none}
  #plv3 .refpill .r-close{position:absolute;top:7px;inset-inline-end:11px;background:none;border:0;color:var(--ink-muted);font-size:20px;cursor:pointer;line-height:1}

  /* ===== synergy (recommended systems) ===== */
  #plv3 .syn-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
  #plv3 .syn{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:24px;transition:transform .3s var(--spring),border-color .3s}
  #plv3 .syn:hover{transform:translateY(-4px);border-color:rgba(52,211,153,.45)}
  #plv3 .syn .syn-name{font-family:'Rubik';font-weight:800;font-size:18px;color:var(--brand);margin-bottom:10px;display:flex;align-items:center;gap:8px}
  #plv3 .syn p{font-size:14.5px;color:var(--ink-2);margin-bottom:16px;line-height:1.6}
  #plv3 .syn a{color:var(--brand);font-weight:700;font-size:14px;display:inline-flex;align-items:center;gap:5px}

  /* ===== partner banner (above footer) ===== */
  #plv3 .partner{background:linear-gradient(90deg,rgba(52,211,153,.12),transparent);border-top:1px solid var(--border)}
  #plv3 .partner .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-block:28px;flex-wrap:wrap}
  #plv3 .partner strong{display:block;font-size:17px;color:var(--ink);font-family:'Rubik';margin-bottom:3px}
  #plv3 .partner span{font-size:14px;color:var(--ink-2)}
  #plv3 .partner-btn{display:inline-flex;align-items:center;gap:7px;min-height:46px;padding:0 22px;border-radius:12px;background:var(--brand);color:#0c0a13;font-weight:700;text-decoration:none;transition:background .2s,transform .2s;white-space:nowrap}
  #plv3 .partner-btn:hover{background:var(--brand-hover);transform:translateY(-1px)}

  /* rocket lottie inside lead forms */
  #plv3 .rocket-lottie{position:relative;width:100%;max-width:340px;aspect-ratio:1/1;margin:0 auto;filter:hue-rotate(0deg) saturate(1.15)}
  #plv3 .rocket-lottie svg{display:block;width:100%!important;height:100%!important}
  /* text placed INSIDE the lottie speech bubble (counter-rotate hue so it stays readable) */
  #plv3 .bubble-text{position:absolute;top:15%;left:60%;transform:translateX(-50%);width:46%;text-align:center;
    display:flex;flex-direction:column;gap:2px;z-index:2;pointer-events:none;filter:hue-rotate(0deg)}
  #plv3 .bubble-text span{font-size:11px;font-weight:800;color:#241546;line-height:1.2}
  #plv3 .ff-error{color:#ff7a7a;font-size:12.5px;margin:-8px 0 12px;display:none}
  #plv3 .ff-error.show{display:block}

  /* ===== exit popup (every page, after 60s) ===== */
  #plv3 .xp-overlay{position:fixed;inset:0;z-index:200;background:rgba(0,0,0,.72);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;pointer-events:none;transition:opacity .3s}
  #plv3 .xp-overlay.show{opacity:1;pointer-events:auto}
  #plv3 .xp-card{position:relative;background:var(--surface);border:1px solid var(--border-strong);border-radius:20px;max-width:440px;width:100%;padding:36px 30px;box-shadow:0 30px 90px rgba(0,0,0,.65);transform:translateY(24px) scale(.96);transition:transform .4s var(--spring)}
  #plv3 .xp-overlay.show .xp-card{transform:none}
  #plv3 .xp-close{position:absolute;top:12px;inset-inline-end:14px;background:none;border:0;color:var(--ink-muted);font-size:22px;cursor:pointer;line-height:1}
  #plv3 .xp-badge{display:inline-block;font-size:12px;font-weight:700;color:var(--brand);background:rgba(52,211,153,.12);border:1px solid rgba(52,211,153,.3);padding:4px 12px;border-radius:999px;margin-bottom:14px}
  #plv3 .xp-card h3{font-size:22px;margin-bottom:8px;line-height:1.25}
  #plv3 .xp-sub{color:var(--ink-2);font-size:15px;margin-bottom:20px}
  #plv3 .xp-card select{width:100%;background:var(--bg);border:1px solid var(--border-strong);border-radius:12px;padding:15px 14px;color:var(--ink);font-family:inherit;font-size:15px;min-height:54px;margin-bottom:14px}
  #plv3 .xp-success{text-align:center;padding:26px 10px}
  #plv3 .xp-success .ic{font-size:44px;margin-bottom:12px;color:var(--brand)}

  /* ===== interactive screens tabs ===== */
  #plv3 .tabs{display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:26px;border-bottom:1px solid var(--border);padding-bottom:0}
  #plv3 .tabs button{position:relative;border:0;background:none;color:var(--ink-2);font-family:inherit;font-weight:600;font-size:15.5px;
    padding:12px 20px;cursor:pointer;min-height:44px;transition:color .25s}
  #plv3 .tabs button::after{content:"";position:absolute;inset-inline:12px;bottom:-1px;height:2px;background:var(--brand);
    transform:scaleX(0);transition:transform .3s var(--spring)}
  #plv3 .tabs button:hover{color:var(--ink)}
  #plv3 .tabs button.active{color:var(--brand)}
  #plv3 .tabs button.active::after{transform:scaleX(1)}
  #plv3 .tab-view{position:relative;border:1px solid var(--border-strong);border-radius:20px;overflow:hidden;
    box-shadow:0 30px 80px rgba(0,0,0,.5);transition:box-shadow .35s,transform .35s var(--spring)}
  #plv3 .tab-view:hover{box-shadow:0 34px 90px rgba(52,211,153,.28)}
  #plv3 .tab-view .chrome{display:flex;align-items:center;gap:8px;padding:12px 18px;border-bottom:1px solid var(--border);background:rgba(0,0,0,.25)}
  #plv3 .tab-view .chrome i{width:11px;height:11px;border-radius:50%;background:#3a3d3c}
  #plv3 .tab-view .chrome i:first-child{background:#ff5f57}#plv3 .tab-view .chrome i:nth-child(2){background:#febc2e}#plv3 .tab-view .chrome i:nth-child(3){background:#28c840}
  #plv3 .tab-view .chrome .u{margin-inline-start:14px;font-size:12.5px;color:var(--ink-muted)}
  #plv3 .tab-view .screen{position:relative;overflow:hidden}
  #plv3 .tab-view img{display:block;width:100%;height:auto;transition:opacity .3s ease,transform .6s var(--spring)}
  #plv3 .tab-view:hover img{transform:scale(1.03)}
  #plv3 .tab-view img.fade{opacity:0}
  #plv3 .tab-cap{text-align:center;margin-top:22px;font-size:16px;color:var(--ink-2);min-height:24px;transition:opacity .3s}

  /* ===== testimonials ===== */
  #plv3 .revs{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
  #plv3 .rev{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:26px;display:flex;flex-direction:column;
    transition:transform .3s var(--spring),border-color .3s,box-shadow .3s}
  #plv3 .rev:hover{transform:translateY(-6px);border-color:rgba(52,211,153,.4);box-shadow:0 20px 50px rgba(52,211,153,.14)}
  #plv3 .rev .stat{font-family:'Rubik';font-weight:800;font-size:34px;color:var(--brand);line-height:1}
  #plv3 .rev .unit{font-size:13px;color:var(--ink-muted);margin:4px 0 16px}
  #plv3 .rev .quote{font-size:15.5px;color:var(--ink);line-height:1.75;flex:1;margin-bottom:20px}
  #plv3 .rev .who{display:flex;align-items:center;gap:11px}
  #plv3 .rev .av{width:44px;height:44px;border-radius:50%;flex:none;display:grid;place-items:center;font-weight:800;color:var(--brand);
    background:radial-gradient(circle at 30% 30%,rgba(52,211,153,.4),rgba(52,211,153,.12));border:1px solid rgba(52,211,153,.3)}
  #plv3 .rev .who b{font-size:14.5px;display:block}
  #plv3 .rev .who span{font-size:12.5px;color:var(--ink-muted)}

  /* ===== stat band (count-up) ===== */
  #plv3 .band{border-block:1px solid var(--border);background:var(--soft)}
  #plv3 .band .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;padding-block:48px;text-align:center}
  #plv3 .band .n{font-family:'Rubik';font-weight:800;font-size:clamp(30px,4.4vw,44px);color:var(--brand)}
  #plv3 .band .l{font-size:14px;color:var(--ink-2);margin-top:6px}

  /* section head */
  #plv3 .sec-head{text-align:center;max-width:660px;margin:0 auto 56px}
  #plv3 .sec-head .eyebrow{color:var(--brand);font-weight:700;font-size:14px;letter-spacing:.06em;margin-bottom:12px}
  #plv3 .sec-head h2{font-size:clamp(28px,4.4vw,46px);margin-bottom:14px}
  #plv3 .sec-head p{color:var(--ink-2);font-size:17px}

  /* ===== features ===== */
  #plv3 .features{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
  #plv3 .feat{position:relative;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:28px;
    transition:transform .3s var(--spring),border-color .3s,background .3s;overflow:hidden}
  #plv3 .feat:hover{transform:translateY(-6px);border-color:rgba(52,211,153,.45);background:var(--soft)}
  #plv3 .feat .ic{width:52px;height:52px;border-radius:14px;display:grid;place-items:center;margin-bottom:18px;font-size:24px;
    background:rgba(52,211,153,.12);border:1px solid rgba(52,211,153,.25);transition:transform .3s var(--spring)}
  #plv3 .feat:hover .ic{transform:scale(1.1) rotate(-4deg)}
  #plv3 .feat h3{font-size:20px;margin-bottom:10px}
  #plv3 .feat p{color:var(--ink-2);font-size:15px;margin-bottom:18px}
  #plv3 .feat .more{color:var(--brand);font-weight:700;font-size:14.5px;display:inline-flex;align-items:center;gap:6px}
  #plv3 .feat .more .arr{transition:transform .25s var(--spring)}
  #plv3 .feat:hover .more .arr{transform:translateX(-6px)}
  #plv3 .feat .badge{position:absolute;top:18px;inset-inline-start:18px;font-size:11px;font-weight:700;color:var(--neon);
    background:rgba(110,231,183,.1);border:1px solid rgba(110,231,183,.28);padding:3px 9px;border-radius:999px}

  /* ===== agent team orbit ===== */
  #plv3 .orbit-wrap{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
  #plv3 .orbit{position:relative;width:min(440px,90vw);aspect-ratio:1;margin:0 auto}
  #plv3 .orbit .core{position:absolute;inset:38%;border-radius:50%;display:grid;place-items:center;font-size:30px;
    background:radial-gradient(circle at 35% 30%,rgba(52,211,153,.45),rgba(52,211,153,.12));
    border:1px solid rgba(52,211,153,.5);box-shadow:0 0 40px rgba(52,211,153,.35)}
  #plv3 .orbit .ring{position:absolute;inset:0;border:1px dashed var(--border-strong);border-radius:50%}
  #plv3 .orbit .ring.r2{inset:15%}
  #plv3 .spin{position:absolute;inset:0;animation:spin 26s linear infinite}
  @keyframes spin{to{transform:rotate(360deg)}}
  #plv3 .node{position:absolute;top:50%;left:50%;width:78px;height:78px;margin:-39px;border-radius:50%;
    background:var(--surface);border:1px solid rgba(52,211,153,.35);display:grid;place-items:center;
    box-shadow:0 8px 24px rgba(0,0,0,.4);animation:counter 26s linear infinite}
  @keyframes counter{to{transform:rotate(-360deg)}}
  #plv3 .node .em{font-size:26px}
  #plv3 .node .tag{position:absolute;bottom:-22px;font-size:11px;color:var(--ink-2);white-space:nowrap;font-weight:600}
  #plv3 .n1{transform:translate(0,-190px)} #plv3 .n2{transform:translate(165px,95px)} #plv3 .n3{transform:translate(-165px,95px)}
  #plv3 .orbit-copy h2{font-size:clamp(26px,4vw,40px);margin-bottom:16px}
  #plv3 .orbit-copy p{color:var(--ink-2);font-size:17px;margin-bottom:16px}
  #plv3 .orbit-copy .role-list{display:flex;flex-direction:column;gap:10px}
  #plv3 .orbit-copy .role{display:flex;gap:10px;align-items:center;font-size:15px;color:var(--ink)}
  #plv3 .orbit-copy .role b{color:var(--brand)}
  #plv3 .orbit-copy .role .d{width:7px;height:7px;border-radius:50%;background:var(--brand);flex:none}

  /* ===== steps ===== */
  #plv3 .steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;counter-reset:s}
  #plv3 .step{position:relative;padding-top:14px}
  #plv3 .step::before{counter-increment:s;content:"0" counter(s);font-family:'Rubik';font-weight:800;font-size:46px;
    color:transparent;-webkit-text-stroke:1.5px rgba(52,211,153,.55);display:block;margin-bottom:14px}
  #plv3 .step h3{font-size:18px;margin-bottom:8px}
  #plv3 .step p{color:var(--ink-2);font-size:14.5px}
  #plv3 .step:not(:last-child)::after{content:"";position:absolute;top:36px;inset-inline-start:-11px;width:22px;height:2px;background:var(--border-strong)}

  /* ===== autonomy switch (interactive) ===== */
  #plv3 .auto{max-width:780px;margin:0 auto;text-align:center}
  #plv3 .switch{position:relative;display:inline-flex;background:var(--surface);border:1px solid var(--border-strong);
    border-radius:999px;padding:5px;margin-bottom:30px;gap:2px}
  #plv3 .switch button{position:relative;z-index:1;border:0;background:none;color:var(--ink-2);font-family:inherit;font-weight:700;
    font-size:15px;padding:11px 26px;border-radius:999px;cursor:pointer;transition:color .3s;min-height:44px}
  #plv3 .switch button.active{color:#06130D}
  #plv3 .switch .glide{position:absolute;z-index:0;top:5px;bottom:5px;border-radius:999px;background:var(--brand);
    transition:all .4s var(--spring)}
  #plv3 .auto-panel{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:34px;min-height:150px}
  #plv3 .auto-panel h3{font-size:22px;margin-bottom:10px;color:var(--brand)}
  #plv3 .auto-panel p{color:var(--ink-2);font-size:16px}
  #plv3 .auto-panel .st{display:inline-block;margin-top:14px;font-size:13px;color:var(--ink-muted)}

  /* ===== pricing ===== */
  #plv3 .prices{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;align-items:stretch}
  #plv3 .price{position:relative;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:30px;
    display:flex;flex-direction:column;transition:transform .3s var(--spring),border-color .3s}
  #plv3 .price:hover{transform:translateY(-5px);border-color:rgba(52,211,153,.4)}
  #plv3 .price.pop{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand),0 20px 50px rgba(52,211,153,.14)}
  #plv3 .price .tag{position:absolute;top:-12px;inset-inline-start:50%;transform:translateX(50%);background:var(--brand);color:#06130D;
    font-size:12px;font-weight:700;padding:4px 14px;border-radius:999px}
  #plv3 .price h3{font-size:19px;margin-bottom:6px}
  #plv3 .price .amt{font-family:'Rubik';font-weight:800;font-size:40px;margin:8px 0 2px}
  #plv3 .price .amt small{font-size:15px;color:var(--ink-muted);font-weight:600}
  #plv3 .price .desc{color:var(--ink-muted);font-size:14px;margin-bottom:18px}
  #plv3 .price ul{list-style:none;margin-bottom:22px;display:flex;flex-direction:column;gap:10px;flex:1}
  #plv3 .price li{font-size:14.5px;color:var(--ink-2);display:flex;gap:9px;align-items:flex-start}
  #plv3 .price li::before{content:"✓";color:var(--brand);font-weight:800;flex:none}
  #plv3 .price .btn{width:100%}

  /* ===== faq ===== */
  #plv3 .faq{max-width:760px;margin:0 auto}
  #plv3 .q{border:1px solid var(--border);border-radius:14px;background:var(--surface);margin-bottom:12px;overflow:hidden}
  #plv3 .q summary{list-style:none;cursor:pointer;padding:20px 22px;display:flex;justify-content:space-between;align-items:center;font-weight:600;font-size:16.5px;min-height:44px}
  #plv3 .q summary::-webkit-details-marker{display:none}
  #plv3 .q summary .plus{color:var(--brand);font-size:22px;transition:transform .3s var(--spring);flex:none;margin-inline-start:14px}
  #plv3 .q[open] summary .plus{transform:rotate(135deg)}
  #plv3 .q .a{padding:0 22px 20px;color:var(--ink-2);font-size:15px}

  /* final */
  #plv3 .final{position:relative;text-align:center;background:linear-gradient(180deg,var(--soft),var(--bg))}
  #plv3 .final h2{font-size:clamp(30px,5vw,50px);margin-bottom:16px}
  #plv3 .final p{color:var(--ink-2);font-size:18px;margin-bottom:30px}

  /* footer */
  #plv3 footer{border-top:1px solid var(--border);padding-block:48px 30px;color:var(--ink-muted);font-size:14px}
  #plv3 .foot-grid{display:flex;justify-content:space-between;flex-wrap:wrap;gap:28px;margin-bottom:32px}
  #plv3 .foot-grid h5{color:var(--ink);font-size:14px;margin-bottom:14px;font-weight:700}
  #plv3 .foot-grid a{display:block;color:var(--ink-muted);margin-bottom:9px;font-size:14px;transition:color .2s}
  #plv3 .foot-grid a:hover{color:var(--brand)}
  #plv3 .foot-bottom{border-top:1px solid var(--border);padding-top:22px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}

  /* reveal + stagger */
  #plv3 .reveal{opacity:0;transform:translateY(28px);transition:opacity .7s var(--spring),transform .7s var(--spring);transition-delay:calc(var(--i,0)*90ms)}
  #plv3 .reveal.in{opacity:1;transform:none}
  @media (prefers-reduced-motion:reduce){
    #plv3 *{animation:none!important}
    #plv3 .reveal,#plv3 .mock{opacity:1!important;transform:none!important}
    #plv3 .spin,#plv3 .node{animation:none!important}
    #plv3 .m-bars .b{transition:none}
  }

  #plv3 header.mobile-open .nav-links{display:flex!important;position:absolute;top:68px;inset-inline:0;flex-direction:column;
    align-items:flex-start;background:var(--bg);border-bottom:1px solid var(--border);padding:18px 24px;gap:18px;z-index:99}
  @media(max-width:900px){
    #plv3 .nav-links,#plv3 .nav-cta .btn-ghost,#plv3 .lang{display:none}
    #plv3 .burger{display:block}
    #plv3 .features,#plv3 .steps,#plv3 .prices,#plv3 .band .wrap,#plv3 .revs,#plv3 .syn-grid{grid-template-columns:1fr 1fr}
    #plv3 .mock-body{grid-template-columns:1fr}#plv3 .mock-side{display:none}
    #plv3 .m-cards{grid-template-columns:1fr 1fr}
    #plv3 .orbit-wrap,#plv3 .how-layout{grid-template-columns:1fr;gap:30px}
    #plv3 .how-lottie{max-width:280px}
    #plv3 .lead-card{grid-template-columns:1fr;gap:26px;padding:30px}
    #plv3 .lead-visual{order:-1;min-height:170px}
  }
  @media(max-width:560px){
    #plv3 .features,#plv3 .steps,#plv3 .prices,#plv3 .band .wrap,#plv3 .revs,#plv3 .syn-grid{grid-template-columns:1fr}
    #plv3 .foot-grid{flex-direction:column}
    #plv3 .switch button{padding:11px 16px;font-size:13.5px}
  }


  #plv3 .pc-layout{display:grid;grid-template-columns:200px 1fr;gap:28px;align-items:start;max-width:1000px;margin:0 auto}
  #plv3 .pc-side-desktop{position:sticky;top:100px;display:flex;flex-direction:column;gap:3px}
  #plv3 .pc-side-mobile{display:none}
  #plv3 .pc-side-item{text-align:right;padding:11px 14px;border:none;border-inline-end:2px solid transparent;background:transparent;color:var(--ink-muted);font-size:15px;font-weight:600;cursor:pointer;border-radius:8px 0 0 8px;transition:all .2s;font-family:inherit}
  #plv3 .pc-side-item:hover{background:color-mix(in srgb,var(--brand) 6%,transparent);color:var(--ink)}
  #plv3 .pc-side-item.active{background:color-mix(in srgb,var(--brand) 10%,transparent);color:var(--brand);border-inline-end-color:var(--brand);font-weight:700}
  #plv3 .pc-side-tag{display:block;font-size:11px;color:var(--ink-muted);margin-top:1px;font-weight:400;direction:ltr;text-align:right}
  #plv3 .pc-side-item.active .pc-side-tag{color:var(--brand);opacity:.7}
  #plv3 .pc-carousel-area{position:relative}
  #plv3 .pc-wrap{perspective:1200px;position:relative;height:580px;overflow:visible;cursor:pointer}
  #plv3 .pc-card{position:absolute;top:0;left:50%;width:340px;margin-left:-170px;border:1px solid color-mix(in srgb,var(--brand) 15%,transparent);
    border-radius:16px;padding:26px 22px;background:var(--surface);transition:all .6s cubic-bezier(.25,.8,.25,1);backface-visibility:hidden}
  #plv3 .pc-card.center{transform:translateX(0) translateZ(0) rotateY(0) scale(1);z-index:30;opacity:1;border-color:color-mix(in srgb,var(--brand) 42%,transparent);box-shadow:0 0 50px color-mix(in srgb,var(--brand) 16%,transparent);cursor:default}
  #plv3 .pc-card.right{transform:translateX(66%) translateZ(-150px) rotateY(-18deg) scale(.8);z-index:20;opacity:.8;filter:blur(.5px) brightness(.9);cursor:pointer}
  #plv3 .pc-card.left{transform:translateX(-66%) translateZ(-150px) rotateY(18deg) scale(.8);z-index:20;opacity:.8;filter:blur(.5px) brightness(.9);cursor:pointer}
  #plv3 .pc-card.far-right{transform:translateX(116%) translateZ(-300px) rotateY(-28deg) scale(.62);z-index:10;opacity:.4;filter:blur(2px) brightness(.82);cursor:pointer}
  #plv3 .pc-card.far-left{transform:translateX(-116%) translateZ(-300px) rotateY(28deg) scale(.62);z-index:10;opacity:.4;filter:blur(2px) brightness(.82);cursor:pointer}
  #plv3 .pc-card.hidden-card{transform:translateX(0) translateZ(-500px) scale(.4);z-index:1;opacity:0;pointer-events:none}
  #plv3 .pc-nav{display:flex;justify-content:center;gap:16px;margin-top:30px}
  #plv3 .pc-btn{width:44px;height:44px;border-radius:50%;border:1px solid color-mix(in srgb,var(--brand) 30%,transparent);background:color-mix(in srgb,var(--brand) 5%,transparent);color:var(--brand);font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .2s}
  #plv3 .pc-btn:hover{background:color-mix(in srgb,var(--brand) 15%,transparent);border-color:var(--brand)}
  #plv3 .pc-dots{display:flex;justify-content:center;gap:8px;margin-top:16px}
  #plv3 .pc-dot{width:8px;height:8px;border-radius:50%;background:color-mix(in srgb,var(--brand) 22%,transparent);border:none;cursor:pointer;transition:all .3s;padding:0}
  #plv3 .pc-dot.active{background:var(--brand);width:24px;border-radius:4px}
  #plv3 .pc-popular{position:absolute;top:-12px;inset-inline-end:20px;background:var(--brand);color:#0c0a13;font-size:11px;font-weight:700;padding:4px 12px;border-radius:20px}
  #plv3 .pc-header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;gap:10px}
  #plv3 .pc-name{font-size:1.15rem;font-weight:700;color:var(--ink);font-family:'Rubik'}
  #plv3 .pc-price{font-size:1.6rem;font-weight:800;color:var(--brand);text-align:left;line-height:1.1;direction:ltr;font-family:'Rubik'}
  #plv3 .pc-price small{font-size:.9rem;font-weight:700}
  #plv3 .pc-price-note{font-size:.68rem;color:var(--ink-muted);text-align:left}
  #plv3 .pc-desc{font-size:.84rem;color:var(--ink-2);line-height:1.6;margin-bottom:14px}
  #plv3 .pc-target{font-size:.75rem;color:var(--ink-muted);font-style:italic;margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid var(--border)}
  #plv3 .pc-items{list-style:none;margin-bottom:14px;padding:0}
  #plv3 .pc-items li{display:flex;align-items:flex-start;gap:8px;font-size:.84rem;color:var(--ink-2);padding:4px 0}
  #plv3 .pc-check{color:var(--brand);flex-shrink:0;font-weight:700}
  #plv3 .pc-benefits{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:14px}
